import{z as i,x as A,o as r,c as p,q as n,j as B,D as e,d as t,s,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"期权多腿与复杂单","description":"","frontmatter":{"title":"期权多腿与复杂单","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/options-complex-orders.md","filePath":"quant/options-complex-orders.md","lastUpdated":1791063341000}'),d={name:"quant/options-complex-orders.md"};function m(u,a,c,h,f,F){const o=A("Mermaid");return r(),p("div",null,[a[2]||(a[2]=n('<h1 id="期权多腿与复杂单" tabindex="-1">期权多腿与复杂单 <a class="header-anchor" href="#期权多腿与复杂单" aria-label="Permalink to &quot;期权多腿与复杂单&quot;">​</a></h1><div class="epigraph"><p>价差、跨式、转换套利要的是腿与腿同时成交。若拆成单腿去各簿上抢，执行风险会吞掉结构本身的边。复杂订单簿把一篮子指令当成一个匹配对象。</p><footer>—— 据 Harris 对组合指令与期权市场结构的论述；对照 Muravyev, Order flow and expected option returns, Journal of Finance, 2016 对期权订单流信息的讨论</footer></div><p><a href="/quant/futures-matching-algo">期货匹配</a>说明底层领先市场的撮合可以不是 FIFO。缺口是期权：价格是多维的（合约、执行价、到期），做市商报的是希腊值约束下的一整面，客户要的是多腿同时成交。CBOE 一类场所提供复杂订单簿（COB）。本课写为何单腿 LOB 不够，以及复杂匹配如何改变逆向选择与抢腿风险。不把期权定价公式重推一遍。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>买一个看涨、卖一个看跌去合成期货，若两腿分两次成交，中间市场一动，合成价就偏。速度竞赛在这里变成「抢尚未完成的腿」。复杂单要求引擎按净价匹配一篮子，要么全成要么不成（或按规则部分）。问题是流动性供给如何组织：做市商在复杂簿上报价，还是只在单腿上挂、由引擎自动组合？前者厚但碎片化（每一个结构一张簿），后者依赖单腿深度与组合爆炸。</p><p><span class="marginnote">直觉类比：多腿成交就像一手交钱一手交货。如果先把看涨那腿递出去、等着成交看跌，中间价格一变你就吃亏——「抢腿」抢的就是你换手之间的空档。复杂订单簿干的事，是把两只手绑成一次击掌。</span></p><p><span class="marginnote">数字实例：合成多头 = 买看涨 + 卖看跌。假设看涨在 2.00 成交后标的瞬间跳了 0.5%，看跌那腿要多付 0.15 才能补上——每份合约损 0.15，一张 100 份的合约就是 1500 美元凭空蒸发，结构还没建完，边已被市场吃掉。</span></p><p>Muravyev 等表明期权订单流携带关于标的的信息。复杂单可能是对冲（非知情）也可能是方向性结构（知情）。筛选比股票更难：同一净 delta 可以来自完全不同的意图。</p><h3 id="与标的市场的同步" tabindex="-1">与标的市场的同步 <a class="header-anchor" href="#与标的市场的同步" aria-label="Permalink to &quot;与标的市场的同步&quot;">​</a></h3><p>做市商的库存是标的、期货、期权多腿的联合。Ho–Stoll 偏度在期权上表现为整面移动。复杂成交立刻在希腊值上留下暴露，必须到标的或期货上对冲——于是期权复杂撮合的时钟与期货算法、股票 NBBO 绑在一起。任何一腿的颠簸或拍卖不同步，都会变成抢腿。</p><p><span class="marginnote">PIN 风险、到期日、做市义务在期权上更重，已有专门课。本课只补「多腿作为一条指令」的市场设计。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>复杂簿的状态是净价与各腿比率，匹配仍是价格优先，时间优先或分配规则因所而异。做市商常享受复杂询价（RFQ）与电子簿并存。比较：强制电子复杂匹配 vs 楼层公开喊价（历史上的 pit）。质量：组合的有效价差相对「沿单腿扫」的复制成本、锁腿失败率、对标的的反馈冲击。</p><p><span class="marginnote">术语翻译：RFQ（询价请求）就是「喊价问一圈」——把你想要的结构报给几家做市商，他们各自回一个净价，你挑最好的成交。电子簿挂不上的薄门类、奇异比例，通常只能走这条路。</span></p><p>信息：复杂单若被拆进单腿磁带，公开可能只看到一条腿，信号残缺。事后透明的设计决定股票市场是否读到期权结构流。</p>',15)),(r(),B(l,null,{default:e(()=>[s(o,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20LR%0A%20%20Struct%5B%22%E5%A4%9A%E8%85%BF%E7%BB%93%E6%9E%84%E6%84%8F%E5%90%91%22%5D%20--%3E%20COB%5B%22%E5%A4%8D%E6%9D%82%E7%B0%BF%E6%8C%89%E5%87%80%E4%BB%B7%E5%8C%B9%E9%85%8D%22%5D%0A%20%20Struct%20--%3E%20Legs%5B%22%E5%88%86%E8%85%BF%E6%8A%A2%E6%88%90%3A%20%E6%89%A7%E8%A1%8C%E9%A3%8E%E9%99%A9%22%5D%0A%20%20COB%20--%3E%20Hedge%5B%22%E5%81%9A%E5%B8%82%E5%95%86%E5%AF%B9%E5%86%B2%E5%88%B0%E6%A0%87%E7%9A%84%20%2F%20%E6%9C%9F%E8%B4%A7%22%5D%0A%20%20Legs%20--%3E%20Hedge%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"复杂匹配提供同时性这种公共品，减少抢腿这种相对速度租金。它是 FBA 思想在合约篮子上的亲戚：批的是腿之间的同时，而不一定是时间上的毫秒批。代价是每一种结构流动性更薄，做市商要求更宽的净价差，或要求看到身份（RFQ）。匿名电子复杂簿与披露客户的询价之间，又是透明权衡。",-1)),a[5]||(a[5]=E("p",null,"对 Glosten 曲线：复杂单的「深度」是净价维度上的供给，不能从单腿 L2 相加得到——相加忽略希腊值对冲成本与跳跃风险。沿单腿复制会高估可成交性。",-1)),(r(),B(l,null,{default:e(()=>[s(o,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E8%A6%81%E4%BC%B0%E8%AE%A1%E7%BB%93%E6%9E%84%E5%8D%95%E7%9A%84%E7%9C%9F%E5%AE%9E%E6%B7%B1%E5%BA%A6%22%5D%20--%3E%20P1%5B%22%E9%94%99%E8%AF%AF%E5%81%9A%E6%B3%95%EF%BC%9A%E5%8D%95%E8%85%BFL2%E7%9B%B8%E5%8A%A0%22%5D%0A%20%20Q%20--%3E%20P2%5B%22%E6%AD%A3%E7%A1%AE%E5%81%9A%E6%B3%95%EF%BC%9A%E7%9C%8B%E5%87%80%E4%BB%B7%E7%BB%B4%E5%BA%A6%E4%BE%9B%E7%BB%99%22%5D%0A%20%20P1%20--%3E%20X1%5B%22%E5%BF%BD%E7%95%A5%E5%B8%8C%E8%85%8A%E5%80%BC%E5%AF%B9%E5%86%B2%E6%88%90%E6%9C%AC%22%5D%0A%20%20P1%20--%3E%20X2%5B%22%E5%BF%BD%E7%95%A5%E8%B7%B3%E8%B7%83%E4%B8%8E%E5%BA%93%E5%AD%98%E9%A3%8E%E9%99%A9%22%5D%0A%20%20X1%20--%3E%20Y%5B%22%E9%AB%98%E4%BC%B0%E5%8F%AF%E6%88%90%E4%BA%A4%E6%80%A7%22%5D%0A%20%20X2%20--%3E%20Y%0A%20%20P2%20--%3E%20Z%5B%22%E5%87%80%E4%BB%B7%E5%B7%AE%E5%B7%B2%E5%90%AB%E5%AF%B9%E5%86%B2%E8%A1%A5%E5%81%BF%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>结构种类组合爆炸，不可能每一种都有厚簿。标准化的常用价差有簿，奇异比例靠询价。美式期权提前行权、公司行动，使「同时」在事后仍可能拆开。零售多腿常被批发商内化，下一课的股票零售流在期权上同样存在。本课不覆盖期权做市的全部存货管理。</p><p><span class="marginnote">回测用单腿中点加总当「公平净价」，忽略同时成交约束，会编造不存在的套利。</span></p><p>股票零售市价多数根本不进公开复杂簿或单腿簿，而是被批发商内化。下一课问：当低毒流被抽走，公开曲线开口如何变。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>多腿需要同时性；复杂订单簿按净价匹配，减少抢腿，但把流动性碎片化到结构上。</li><li>期权流含标的信息，复杂单的筛选与磁带打印改变发现。</li><li>做市库存是联合希腊值，对冲时钟与期货/股票设计耦合。</li><li>出处：Harris, <em>Trading and Exchanges</em>；期权订单流见 Muravyev, <em>Journal of Finance</em>, 2016。</li></ul>',6))])}const _=i(d,[["render",m]]);export{D as __pageData,_ as default};
